import{z as s,x as B,o as i,c as d,q as E,j as o,D as a,d as r,s as n,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const y=JSON.parse('{"title":"分词 fertility 与公平","description":"","frontmatter":{"title":"分词 fertility 与公平","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tokenizer-fertility.md","filePath":"llm/tokenizer-fertility.md","lastUpdated":1791063341000}'),p={name:"llm/tokenizer-fertility.md"};function f(k,e,m,h,D,u){const l=B("Mermaid");return i(),d("div",null,[e[2]||(e[2]=E('<h1 id="分词-fertility-与公平" tabindex="-1">分词 fertility 与公平 <a class="header-anchor" href="#分词-fertility-与公平" aria-label="Permalink to &quot;分词 fertility 与公平&quot;">​</a></h1><div class="epigraph"><p>同一句话在英语里可能是十几个 token，在另一种语言里是四十个；窗口、批量和按 token 计费都会把这种差异写成「能力差距」。</p><footer>—— Petrov 等，Language Model Tokenizers Introduce Unfairness Between Languages，NeurIPS 2023</footer></div><p><a href="/llm/tokenizer-training-corpus">上一课</a>把词表钉在一份分层语料上。平均压缩率好看，并不表示每一种语言、每一个领域都被同等压缩。本课不重讲语料如何抽样。缺口是：fertility（通常定义为每词或每字符的 token 数）把切分偏见变成可计量的税率，后续的配比、窗口和账单都会乘上这个税率。glitch token 是极端的长尾；本课先看平均值与分位数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/tokenizer-design">分词器设计</a>已经提到跨语言不公平。Petrov 等人把多语言基准按「同样语义内容消耗多少 token」摊开：以英语为 1，部分语言要付数倍长度。原因在前几课里已经备齐——<a href="/llm/pretokenization-regex">预分词正则</a> 的类别假设、<a href="/llm/byte-fallback">字节回退</a> 对罕见文字的拆解、合并名额被词表语料里的高频语言占满。缺的是：预训练工程要把这个倍数写进数据加载器与评测协议，而不是只写在分析论文里。</p><p>按 token 均匀的配比，对高 fertility 语言是「同样百分比、更少的句子」。按文档均匀则相反，短英文页会冲淡长 CJK 页。无论哪一种，若不报 fertility，配比数字没有跨语言含义。Rust 等人对「你的 tokenizer 好不好」的评测，也是在问覆盖与下游，而不是只问词表大小。</p><p><span class="marginnote">fertility 说白了就是「压缩率的倒数」：一个词平均被切成几个 token。数字实例：英语 1 个词约切 1.3 个 token，某语言同样的意思要切 4 个，相当于同一句话多付 3 倍的 token 税，窗口也 3 倍快用完。</span></p><h3 id="领域税与语言税叠在一起" tabindex="-1">领域税与语言税叠在一起 <a class="header-anchor" href="#领域税与语言税叠在一起" aria-label="Permalink to &quot;领域税与语言税叠在一起&quot;">​</a></h3><p>代码的标识符、LaTeX、表格数字（尤其 <a href="/llm/digit-splitting">逐位切分</a> 之后）会把 fertility 抬高。这不是语言不公平，是领域税。报表必须交叉：语言 × 桶。否则会把「代码切得碎」误诊成「英语词表歧视符号」，去扩一张无用的多语言表。</p><p><span class="marginnote">常见误区：看到某语言切得碎，就归咎于「词表歧视这门语言」。实际上代码、LaTeX、表格数字这类领域同样会把 token 数抬高。所以必须按「语言 × 领域」交叉统计，否则会扩一张治不了病的多语言词表。</span></p><p><span class="marginnote">产品按 token 收费时，fertility 直接变成用户价格。同一功能在高 fertility 语言上更贵、更容易触顶窗口。这是政策选择，不是模型能力神话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在冻结词表上，对每个语言与每个数据桶计算：字符数 / token 数、空白分词后的词数 / token 数（无空格语言改用字符或语素近似）、回退字节占比、数字 token 占比。画出相对英语（或相对混合语料均值）的倍率。扩表或重训词表的目标函数应包含「降低最高 fertility 分位」，而不只是降低全局平均长度——平均会被英语网页淹没。</p><p>加载器侧有两种补法。一是按「目标语言的有效句子数」而不是按 token 再加权，等于用 fertility 的倒数去调 <a href="/llm/data-mixture-laws">配比</a>。二是给高 fertility 语言更长的序列上限或更小的微批，以免 padding 浪费。前者改数据分布，后者改计算图形状，不要混成一个旋钮。</p><h3 id="评测必须声明单位" tabindex="-1">评测必须声明单位 <a class="header-anchor" href="#评测必须声明单位" aria-label="Permalink to &quot;评测必须声明单位&quot;">​</a></h3><p>下游分数若按「固定 token 预算」截断，高 fertility 语言先被截断，分数掉的是窗口，不是理解。应同时报固定字符/固定文档预算下的分数。Petrov 等人的不公平，很多来自这种静默截断。</p><p><span class="marginnote">特殊 token 与聊天模板也要计入 fertility。一轮中英夹杂的系统提示，可能比用户那句短问题更占窗口。模板本地化不是翻译问题，是 token 税问题。</span></p>',17)),(i(),o(A,null,{default:a(()=>[n(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%86%BB%E7%BB%93%E8%AF%8D%E8%A1%A8%22%5D%20--%3E%20T%5B%22%E6%8C%89%E8%AF%AD%E8%A8%80%20%C3%97%20%E9%A2%86%E5%9F%9F%E6%A1%B6%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20T%20--%3E%20C%5B%22%E5%AD%97%E7%AC%A6%E6%95%B0%E4%B8%8E%20token%20%E6%95%B0%E4%B9%8B%E6%AF%94%22%5D%0A%20%20T%20--%3E%20F%5B%22%E5%9B%9E%E9%80%80%E5%AD%97%E8%8A%82%E5%8D%A0%E6%AF%94%22%5D%0A%20%20T%20--%3E%20N%5B%22%E6%95%B0%E5%AD%97%20token%20%E5%8D%A0%E6%AF%94%22%5D%0A%20%20C%20--%3E%20R%5B%22%E7%9B%B8%E5%AF%B9%E8%8B%B1%E8%AF%AD%E7%9A%84%E5%80%8D%E7%8E%87%E6%8A%A5%E8%A1%A8%22%5D%0A%20%20F%20--%3E%20R%0A%20%20N%20--%3E%20R%0A%20%20R%20--%3E%20P%5B%22%E7%9C%8B%E9%AB%98%E5%88%86%E4%BD%8D%E8%80%8C%E9%9D%9E%E5%85%A8%E7%90%83%E5%B9%B3%E5%9D%87%22%5D%0A%20%20P%20--%3E%20W1%5B%22%E5%80%92%E6%95%B0%E5%8A%A0%E6%9D%83%EF%BC%9A%E8%B0%83%E6%95%B0%E6%8D%AE%E9%85%8D%E6%AF%94%22%5D%0A%20%20P%20--%3E%20W2%5B%22%E8%B0%83%E5%BD%A2%E7%8A%B6%EF%BC%9A%E5%8A%A0%E9%95%BF%E4%B8%8A%E9%99%90%E6%88%96%E5%87%8F%E5%B0%8F%E5%BE%AE%E6%89%B9%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"fertility 是切分函数 \\(f\\) 在测度 \\(p\\) 上的期望长度。\\(p\\) 来自词表语料与模型语料的错位、以及 Unicode 覆盖。长度进入注意力的二次项与 KV 缓存，于是同样的「上下文 8k」对低 fertility 语言是一篇文章，对高 fertility 语言是一段。MoE 的专家粒度课已经假设 token 是均匀的计算单位；本课指出这个单位对用户语言并不是均匀的语义单位。",-1)),e[5]||(e[5]=t("p",null,[t("span",{class:"marginnote"},"数字实例：同样是 8k 窗口，fertility 为 1.3 的语言大约装得下六千词的文章；fertility 为 4 的语言只能装约两千词。而且注意力的计算量和 KV 缓存都随长度增长，同样一句话的后端开销也差出几倍。")],-1)),(i(),o(A,null,{default:a(()=>[n(l,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%88%87%E5%88%86%E5%87%BD%E6%95%B0%22%5D%20--%3E%20L%5B%22%E5%90%84%E8%AF%AD%E8%A8%80%E5%BA%8F%E5%88%97%E9%95%BF%E5%BA%A6%22%5D%0A%20%20L%20--%3E%20W%5B%22%E6%9C%89%E6%95%88%E7%AA%97%E5%8F%A3%22%5D%0A%20%20L%20--%3E%20MIX%5B%22%E6%8C%89%20token%20%E9%85%8D%E6%AF%94%E7%9A%84%E7%9C%9F%E5%AE%9E%E5%8F%A5%E5%AD%90%E6%95%B0%22%5D%0A%20%20L%20--%3E%20FEE%5B%22%E6%8C%89%20token%20%E8%AE%A1%E8%B4%B9%22%5D%0A%20%20W%20--%3E%20EVAL%5B%22%E6%88%AA%E6%96%AD%E5%90%8E%E7%9A%84%E8%AF%84%E6%B5%8B%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>把英语 fertility 降到极限（超大词表、整词化）会伤害形态泛化，并制造更多欠训符号——下一课 glitch。公平也不是把所有语言拉到同一 token 数：形态丰富的语言可能需要更碎的切分才能组合。目标应是「同语义内容的长度比」落在可接受区间，并在产品层用配比与窗口补偿剩余差距。不要为了报表好看把数字重新焊成整块，那是牺牲算术对齐去买压缩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲词表语料抽样；只补长度倍率如何变成窗口税与配比税。</li><li>fertility 应按语言 × 领域交叉统计，并用高分位而不是全球平均做优化目标。</li><li>按 token 的配比与评测截断会把切分偏见写成能力差距。</li><li>可用倒数加权补偿，但不要回退到乱焊数字。</li><li>出处：Petrov et al., NeurIPS 2023；Rust et al., <em>How Good is Your Tokenizer?</em>, ACL 2021。</li></ul>',4))])}const F=s(p,[["render",f]]);export{y as __pageData,F as default};
